insert into public.preview_catalogo_maestro_platos
  (plato_id, sinonimos, resumen, hack, que_observar, activo)
values
  ('pizza', ARRAY['pizza', 'pizza muzza', 'pizza de mozzarella', 'porcion de pizza']::text[], 'El clásico urbano por excelencia. Combina una base de harina refinada fermentada con salsa de tomate y un colchón fundido de mozzarella (carbohidratos de rápida absorción y grasas lácteas).', 'Modera la porción y acompañala obligatoriamente con una buena entrada de hojas verdes con vinagre; esa fibra inicial frena el impacto glucémico directo de la masa. El toque fit de valor: si tenés la opción, elegí versiones con masa madre o harina integral; la fermentación natural de la masa madre predigiere el gluten y mejora radicalmente la asimilación y el nivel de energía posterior. Tip extra: un toque de aceite de oliva con ají molido arriba estimula la termogénesis y la digestión.', 'Registra la velocidad con la que reaparece el hambre y la sensación de sed posterior; notarás una diferencia abismal en la liviandad si optas por la variante de masa madre frente a la harina blanca común.', false),
  ('pizza-especial-jamon', ARRAY['pizza especial', 'pizza con jamon', 'pizza jamon y morrones']::text[], 'Evolución de la clásica muzza que suma un aporte proteico extra gracias al jamón cocido, elevando la densidad general del plato.', 'Al igual que con la pizza base, prioriza comerla despacio y complementarla con vegetales frescos. Tip extra: si el jamón es muy salado, un toque de oliva virgen extra equilibra la palatabilidad sin saturar el paladar.', 'Compara tu nivel de saciedad frente a la pizza de mozzarella sola; el aporte de proteína extra suele mantener el apetito a raya por un poco más de tiempo.', false),
  ('pizza-fugazzeta', ARRAY['pizza fugazeta', 'fugazeta', 'pizza con cebolla']::text[], 'Base de masa cubierta por una montaña de cebollas rehogadas y abundante queso fundido. Una combinación de altísimo valor de confort y sabor profundo.', 'Los compuestos sulfurados de la cebolla cocida ayudan a suavizar la digestión de las grasas lácteas del queso. Tip extra: una pizca generosa de orégano seco potencia los antioxidantes y le da un perfil digestivo muy superior.', 'Presta atención a cómo responde tu estómago; las cebollas en gran cantidad pueden generar un leve reflujo si se comen de apuro o muy tarde a la noche.', false),
  ('pizza-ternera', ARRAY['pizza con ternera', 'pizza con carne', 'pizza fugazeta con carne']::text[], 'Una variante ultra contundente que suma carne vacuna desmenuzada o picada sobre la estructura de la pizza. Funciona casi como un plato principal completo.', 'Por su enorme densidad calórica y proteica, reduce la cantidad de porciones habituales; con dos porciones bien saboreadas cubris perfecto la energía. Tip extra: un toque de provenzal o perejil fresco al salir del horno ayuda a mitigar la pesadez de la carne roja combinada con harinas.', 'Evalúa la estabilidad de tu energía posterior; al ser un plato muy pesado, requiere un buen rato de digestión tranquila antes de encarar actividad física o mental intensa.', false),
  ('pizza-calabresa', ARRAY['pizza calabresa', 'pizza con salame', 'calabresa']::text[], 'Pizza con rodajas de embutido curado (salame/longaniza), aportando notas especiadas, grasas de alta intensidad y un perfil de sabor sumamente estimulante.', 'El salame aporta grasas saturadas y sodio elevados; combinala con una porción generosa de ensalada cruda al lado para amortiguar el impacto metabólico general. Tip extra: un toque de pimienta negra o ají molido realza el picor natural sin necesidad de abusar de la cantidad de embutido.', 'Nota la sed posterior y la pesadez estomacal; los embutidos curados combinados con masa de harina blanca exigen una buena hidratación para evitar el letargo.', false),
  ('pizza-rucula', ARRAY['pizza con rucula', 'pizza rucula y parmesano', 'pizza con jamon crudo y rucula']::text[], 'Una de las opciones más equilibradas del mundo pizzerio: la base de masa y queso se complementa con el amargor fresco de la rúcula cruda y viruta de queso duro o jamón.', 'El gran secreto bio-hack: la rúcula cruda aporta fibra viva y compuestos amargos que estimulan la secreción biliar, mejorando notablemente la digestión del queso y la masa. Tip extra: un buen hilo de aceite de oliva crudo por encima de la rúcula al servir eleva el plato a otro nivel.', 'Compara tu liviandad estomacal frente a una pizza pesada de fiambres; la rúcula aporta una frescura que evita la modorra post-comida.', false),
  ('empanada-carne', ARRAY['empanada de carne', 'empanadas de carne', 'empanada criolla', 'empanada cortada a cuchillo']::text[], 'Disco de masa horneado o frito que encierra un jugoso relleno de carne vacuna especiada. Densidad proteica y energética muy portátil.', 'Si elegís la versión al horno, logras un excelente balance; si son fritas, escurriles bien el excedente de aceite en papel. Tip extra: un toque de jugo de limón recién exprimido sobre la empanada abierta activa las papilas y facilita la digestión de la carne.', 'Registra cuántas te llenan realmente; al ser un alimento muy denso, el punto de saciedad llega de golpe y conviene frenar antes de la pesadez.', false),
  ('empanada-pollo', ARRAY['empanada de pollo', 'empanadas de pollo', 'empanada de ave']::text[], 'Variante más ligera en cuanto al tipo de carne, combinando pechuga o pollo desmenuzado con vegetales rehogados dentro de la masa.', 'Acompañalas con una ensalada fresca o un toque de criolla natural para sumar humedad y fibra al plato. Tip extra: un toque de pimentón ahumado en el relleno realza el sabor sin sumar grasas pesadas.', 'Nota la diferencia de liviandad estomacal en comparación con la empanada de carne roja; el pollo suele transitarse con mayor velocidad gástrica.', false),
  ('empanada-verdura', ARRAY['empanada de verdura', 'empanadas de verdura', 'empanada de acelga o espinaca', 'empanada de acelga']::text[], 'Relleno verde a base de acelga o espinaca combinada con cebolla y un toque de queso o ricota. Aporta fibra vegetal y menor carga calórica.', 'Escurrí muy bien la verdura antes de armarlas para evitar que la masa se humedezca de más. Tip extra: una pizca de nuez moscada en el ligue de la verdura realza el sabor clásico y reconfortante.', 'Analiza tu confort digestivo; al tener base vegetal, son sumamente amigables para comer al mediodía sin perder claridad mental.', false),
  ('empanada-choclo', ARRAY['empanada de choclo', 'empanadas de choclo', 'empanada humita']::text[], 'Relleno dulce y cremoso a base de granos de maíz, cebolla y salsa blanca o queso fundido. Aporte importante de carbohidratos de asimilación rápida.', 'Al ser un relleno dulce y denso, moderá la cantidad y combinala con alguna opción salada o proteica si armás surtido. Tip extra: un toque de pimienta negra o ají molido equilibra el dulzor natural del choclo de manera perfecta.', 'Presta atención a la energía inmediata que te aporta; da un pico rápido de glucosa que rinde muy bien si vas a moverte enseguida.', false),
  ('sfija', ARRAY['sfija', 'empanada arabe', 'empanada abierta de carne', 'fatay']::text[], 'Clásica empanada de formato abierto con un relleno jugoso de carne vacuna, tomate, cebolla y un toque característico de limón y especias.', 'Al llevar limón y especias digestivas (como comino o pimentón) integradas en el relleno, la carne se digiere con muchísima más agilidad que en una empanada tradicional cerrada. Tip extra: sumarle unas gotitas extra de limón fresco al comerla potencia su perfil digestivo original.', 'Registra la comodidad post-almuerzo; la acidez natural del relleno suele dejar el estómago mucho más liviano que otras opciones con exceso de grasa.', false),
  ('tarta-jamon-queso', ARRAY['tarta de jamon y queso', 'tartas', 'pascualina de jamon y queso']::text[], 'Clásico de casa o rotisería. Capas de masa de tarta con un corazón denso de jamón y abundante queso derretido. Alto contenido calórico y graso.', 'Una porción generosa acompañada de una buena ensalada de hojas verdes crudas compensa perfectamente la falta de fibra de la tarta. Tip extra: un toque de orégano o provenzal arriba ayuda a cortar la pesadez de los lácteos fundidos.', 'Nota la velocidad de saciedad; es un plato muy denso que sacia rápido pero puede dejar una sensación de modorra si la porción es grande.', false),
  ('tarta-choclo', ARRAY['tarta de choclo', 'tarta de humita', 'pascualina de choclo']::text[], 'Relleno cremoso de maíz tierno ligado con huevo y salsa blanca o queso, contenido en una masa crocante.', 'Si buscás aligerarla, prioriza una masa hojaldrada fina o preparala en versión sin tapa superior para reducir el impacto de las harinas refinadas. Tip extra: un toque de nuez moscada y pimentón realza el sabor del maíz sin necesidad de agregar aditivos pesados.', 'Evalúa tu confort estomacal; el choclo aporta una textura suave pero requiere buena masticación para evitar digestiones lentas.', false),
  ('tarta-verdura', ARRAY['tarta de verdura', 'tarta de acelga', 'tarta de espinaca', 'pascualina']::text[], 'El caballito de batalla de la cocina saludable cotidiana. Acelga o espinaca, huevo y condimentos dentro de una masa consistente.', 'Sumale una porción extra de queso magro o huevo duro picado en el relleno para redondear un perfil proteico completo. Tip extra: un toque de ajo deshidratado o fresco en la verdura eleva el sabor y aporta compuestos protectores hepáticos.', 'Analiza tu liviandad y energía sostenida; es una de las mejores opciones de masa para mantener el rendimiento mental sin altibajos glucémicos.', false),
  ('bombas-carne', ARRAY['bombas de carne', 'papa rellena frita', 'croqueta de carne rellena']::text[], 'Preparación a base de puré de papa moldeado con un corazón de carne picada, rebozado y frito a alta temperatura.', 'Por su doble carga de almidón (papa) y fritura profunda, tratá de consumirlas de forma ocasional y siempre escurridas al máximo. Tip extra: acompáñalas con un dip de limón o salsa natural para contrarrestar la densidad grasa de la fritura.', 'Registra el impacto en tu digestión; al ser una bomba calórica y lipídica, el vaciado gástrico es muy lento y demanda un tiempo largo de reposo.', false),
  ('bombas-queso', ARRAY['bombas de queso', 'croquetas de queso', 'bolitas de queso fritas']::text[], 'Bocados crujientes por fuera con un interior de queso fundido y texturas amalgamadas por el rebozado.', 'Moderá la cantidad como entrada o picada; funcionan mucho mejor como un gusto ocasional que como base de una comida principal. Tip extra: una salsa especiada o un toque de pimienta ayuda a levantar el perfil graso del queso frito.', 'Presta atención a la pesadez o sensación de saciedad pesada; las grasas fritas combinadas con lácteos fundidos exigen una buena tolerancia digestiva.', false),
  ('pastel-papas', ARRAY['pastel de papas', 'pastel de carne y puré', 'pastel de papa']::text[], 'Capas superpuestas de puré de papa y carne picada especiada, gratinadas al horno. El gran confort food de olla y fuente.', 'No satures la capa de puré con exceso de manteca o leche entera; deja que la carne jugosa aporte toda la humedad necesaria. Tip extra: un toque de pimentón dulce o ahumado en la superficie antes de gratinar le da un color y aroma tostado inigualable.', 'Nota la saciedad profunda y el calor reconfortante que deja el plato; al ser denso en carbohidratos y proteínas, es ideal para días de alto desgaste físico.', false)
